\echo '--- Option A: CLUSTER orders on (status, order_date)'
BEGIN;
CLUSTER orders USING orders_status_order_date_idx;
ANALYZE orders;
EXPLAIN (ANALYZE, BUFFERS) $Q;
ROLLBACK;
\echo '--- Option B: covering index (status, order_date) INCLUDE (order_id), after VACUUM'
BEGIN;
DROP INDEX orders_status_order_date_idx;
CREATE INDEX orders_status_order_date_idx ON orders (status, order_date) INCLUDE (order_id);
VACUUM (ANALYZE) orders;
EXPLAIN (ANALYZE, BUFFERS) $Q;
ROLLBACK;
EOF

